export const LANGS = [
  { id: "en", name: "English" },
  { id: "tr", name: "Türkçe" },
  { id: "ar", name: "العربية", rtl: true },
];

let current = "en";

export function detectLang() {
  const prefs = navigator.languages || [navigator.language || "en"];
  for (const l of prefs) {
    const base = String(l).slice(0, 2).toLowerCase();
    if (STRINGS[base]) return base;
  }
  return "en";
}

export function setLang(lang) {
  current = STRINGS[lang] ? lang : "en";
  document.documentElement.lang = current;
  document.documentElement.dir = LANGS.find((l) => l.id === current)?.rtl ? "rtl" : "ltr";
  return current;
}

export function lang() {
  return current;
}

// Plural-aware lookup: uses `key_one`, `key_few`… when a language has them (Arabic has six forms).
const pluralRules = {};
export function tn(key, n, vars = {}) {
  const pr = (pluralRules[current] ||= new Intl.PluralRules(current));
  const cat = pr.select(n);
  const s = STRINGS[current]?.[`${key}_${cat}`] ?? STRINGS[current]?.[key] ?? STRINGS.en[`${key}_${new Intl.PluralRules("en").select(n)}`] ?? STRINGS.en[key] ?? key;
  return Object.entries({ n, ...vars }).reduce((acc, [k, v]) => acc.replaceAll(`{${k}}`, v), s);
}

export function t(key, vars) {
  let s = STRINGS[current]?.[key] ?? STRINGS.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.replaceAll(`{${k}}`, v);
  return s;
}
